import { memo, type ComponentProps } from "react";
import { cn } from "cn";

const tracks = "calc(var(--guide-inset) - 12px) minmax(0, 1fr) calc(var(--guide-inset) - 12px)";
const lines = [
  { position: "inset-x-0 top-[var(--guide-inset)]", vertical: false },
  { position: "inset-x-0 bottom-[var(--guide-inset)]", vertical: false },
  { position: "inset-y-0 left-[var(--guide-inset)]", vertical: true },
  { position: "inset-y-0 right-[var(--guide-inset)]", vertical: true },
];
const corners = [
  "left-[var(--guide-inset)] top-[var(--guide-inset)] -translate-x-1/2 -translate-y-1/2",
  "right-[var(--guide-inset)] top-[var(--guide-inset)] translate-x-1/2 -translate-y-1/2",
  "left-[var(--guide-inset)] bottom-[var(--guide-inset)] -translate-x-1/2 translate-y-1/2",
  "right-[var(--guide-inset)] bottom-[var(--guide-inset)] translate-x-1/2 translate-y-1/2",
];

export const GuideCard = memo(function GuideCard({
  children,
  className,
  ...props
}: ComponentProps<"div"> = {}) {
  return (
    <div
      data-slot="guide-card"
      className={cn(
        "relative isolate min-w-0 w-full [--guide-inset:2rem] sm:[--guide-inset:3rem]",
        className,
      )}
      {...props}
    >
      <div
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 text-muted-foreground/40"
      >
        {lines.map(({ position, vertical }) => (
          <div
            key={position}
            className={`absolute grid gap-6 ${vertical ? "w-px" : "h-px"} ${position}`}
            style={vertical ? { gridTemplateRows: tracks } : { gridTemplateColumns: tracks }}
          >
            <span className="bg-border" />
            <span className="bg-border" />
            <span className="bg-border" />
          </div>
        ))}
        {corners.map((position) => (
          <svg
            key={position}
            viewBox="0 0 24 24"
            fill="none"
            className={`absolute size-6 ${position}`}
          >
            <path
              d="M5 12H19M12 5V19"
              stroke="currentColor"
              strokeWidth="1.5"
              strokeLinecap="round"
            />
          </svg>
        ))}
      </div>
      <div className="relative min-w-0 p-12 sm:p-16">{children}</div>
    </div>
  );
});

"use client";

import { memo, useState, type ComponentType, type SVGProps } from "react";
import {
  BashDark,
  Bun,
  CSSNew,
  HTML5,
  JSON as JsonIcon,
  JavaScript,
  NPM,
  PnpmDark,
  Python,
  ReactDark,
  TypeScript,
  Yarn,
} from "@ridemountainpig/svgl-react";
import { FileCode } from "lucide-react";
import { CopyFeedback } from "./copy-feedback.shared";
import { Highlight, type PrismTheme } from "prism-react-renderer";
import Prism from "prismjs";
import "prismjs/components/prism-javascript";
import "prismjs/components/prism-typescript";
import "prismjs/components/prism-jsx";
import "prismjs/components/prism-tsx";
import "prismjs/components/prism-bash";
import "prismjs/components/prism-json";
import "prismjs/components/prism-css";
import "prismjs/components/prism-markup";
import "prismjs/components/prism-python";
import { toast } from "./toast-store";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "./tabs";
import { GuideCard } from "./guide-card";

Prism.languages.insertBefore("bash", "function", {
  command: {
    pattern: /(^|\s)(?:bunx|bun|npx|npm|pnpm|yarn|shadcn(?:@[^\s]+)?)(?=\s|$)/,
    lookbehind: true,
  },
  url: /\bhttps?:\/\/[^\s"'<>]+/,
});

const prismTheme: PrismTheme = {
  plain: { color: "var(--card-foreground)", backgroundColor: "transparent" },
  styles: [
    {
      types: ["comment", "prolog", "doctype", "cdata"],
      style: { color: "light-dark(#557267, #94a8a0)", fontStyle: "italic" },
    },
    {
      types: ["punctuation", "operator"],
      style: { color: "light-dark(#315d50, #a6b3ad)" },
    },
    {
      types: ["keyword", "tag", "selector", "atrule"],
      style: { color: "light-dark(#00664e, #05dc7f)" },
    },
    {
      types: ["string", "char", "attr-value", "url"],
      style: { color: "light-dark(#285ee8, #6bd8ff)" },
    },
    {
      types: ["number", "boolean", "constant"],
      style: { color: "light-dark(#a85d00, #ffe77a)" },
    },
    {
      types: ["function", "class-name", "property", "attr-name"],
      style: { color: "var(--card-foreground)" },
    },
    {
      types: ["builtin", "important", "command"],
      style: { color: "light-dark(#8244d8, #c29aff)" },
    },
  ],
};

const managerIcons = { bun: Bun, npm: NPM, pnpm: PnpmDark, yarn: Yarn };
const languageIcons: Record<string, ComponentType<SVGProps<SVGSVGElement>>> = {
  javascript: JavaScript,
  js: JavaScript,
  typescript: TypeScript,
  ts: TypeScript,
  jsx: ReactDark,
  tsx: ReactDark,
  bash: BashDark,
  sh: BashDark,
  shell: BashDark,
  css: CSSNew,
  html: HTML5,
  xml: HTML5,
  json: JsonIcon,
  python: Python,
  py: Python,
};

interface CodeBlockProps {
  code?: string;
  language?: string;
  filename?: string;
  showLineNumbers?: boolean;
  commands?: Record<"bun" | "npm" | "pnpm" | "yarn", string>;
  packageManager?: "bun" | "npm" | "pnpm" | "yarn";
  onPackageManagerChange?: (manager: "bun" | "npm" | "pnpm" | "yarn") => void;
  className?: string;
}

export function CodeBlock({
  code = 'const greeting = "Hello, world!";\nconsole.log(greeting);',
  language = "javascript",
  filename = "",
  showLineNumbers,
  commands,
  packageManager,
  onPackageManagerChange,
  className = "",
}: CodeBlockProps = {}) {
  const [manager, setManager] = useState<"bun" | "npm" | "pnpm" | "yarn">("bun");
  const selectedManager = packageManager ?? manager;
  const displayedCode = commands ? commands[selectedManager] : code;
  const displayedLanguage = commands ? "bash" : language;
  const [copyResult, setCopyResult] = useState<{ code: string; success: boolean }>();
  const currentResult = copyResult?.code === displayedCode ? copyResult : undefined;

  async function copyCode() {
    try {
      await navigator.clipboard.writeText(displayedCode);
      setCopyResult({ code: displayedCode, success: true });
      toast.success(
        commands
          ? "Install command copied"
          : displayedLanguage === "text"
            ? "Prompt copied"
            : "Code copied",
      );
    } catch {
      setCopyResult({ code: displayedCode, success: false });
      toast.error("Could not copy. Select the text and copy it manually.");
    }
  }

  const hideHeader = !commands && !filename;
  const header = (
    <CodeBlockHeader
      commands={Boolean(commands)}
      language={displayedLanguage}
      filename={filename}
      copied={currentResult?.success}
      onCopy={copyCode}
    />
  );
  const useGuideBorder =
    !commands && !["text", "bash", "sh", "shell"].includes(displayedLanguage.toLowerCase());
  const content = (
    <div className={!commands ? "relative pr-12" : undefined}>
      {!commands && (
        <button
          type="button"
          aria-label="Copy code"
          title={currentResult?.success ? "Copied!" : "Copy code"}
          onClick={copyCode}
          className="absolute right-2 top-2 inline-flex size-9 items-center justify-center hover:bg-muted focus-visible:outline-2 focus-visible:outline-ring"
        >
          <CopyFeedback copied={currentResult?.success} />
        </button>
      )}
      <CodeBlockRenderer
        code={displayedCode}
        language={displayedLanguage}
        filename={filename}
        showLineNumbers={
          showLineNumbers ??
          (!commands && !["text", "bash", "sh", "shell"].includes(language.toLowerCase()))
        }
        packageManager={commands ? selectedManager : undefined}
      />
    </div>
  );

  return (
    <div className={`lazy-code-block relative w-full min-w-0 text-card-foreground ${className}`}>
      {commands ? (
        <Tabs
          value={selectedManager}
          onValueChange={(value) => {
            const next = value as keyof typeof managerIcons;
            setManager(next);
            onPackageManagerChange?.(next);
          }}
        >
          {header}
          {(["bun", "npm", "pnpm", "yarn"] as const).map((option) => (
            <TabsContent
              key={option}
              value={option}
              className="overflow-hidden rounded-lg surface-raised"
            >
              {selectedManager === option ? content : null}
            </TabsContent>
          ))}
        </Tabs>
      ) : useGuideBorder ? (
        <GuideCard className="[clip-path:inset(12px)]">
          {hideHeader ? (
            content
          ) : (
            <Tabs value="code" className="gap-0">
              <TabsList
                variant="line"
                aria-label="Code file"
                className="absolute left-[calc(var(--guide-inset)+8px)] top-[calc(var(--guide-inset)-1.5rem-6px)] z-10 p-0"
              >
                <TabsTrigger value="code" className="min-h-5 py-0">
                  <CodeLanguageLabel language={displayedLanguage} filename={filename} />
                </TabsTrigger>
              </TabsList>
              <TabsContent value="code">{content}</TabsContent>
            </Tabs>
          )}
        </GuideCard>
      ) : (
        <div className="overflow-hidden rounded-lg surface-raised">{content}</div>
      )}
      <span
        role="status"
        className={
          currentResult && !currentResult.success
            ? "block border-t border-border px-4 py-2 text-xs text-muted-foreground"
            : "sr-only"
        }
      >
        {currentResult?.success
          ? "Code copied to clipboard."
          : currentResult
            ? "Could not copy. Select the code and copy it manually."
            : ""}
      </span>
    </div>
  );
}

function CodeBlockHeader({
  commands,
  language,
  filename,
  copied,
  onCopy,
}: {
  commands: boolean;
  language: string;
  filename: string;
  copied?: boolean;
  onCopy: () => void;
}) {
  return (
    <div className="flex items-center justify-between gap-3">
      {commands ? (
        <PackageManagerTabs />
      ) : !filename && ["text", "bash"].includes(language.toLowerCase()) ? null : (
        <TabsList variant="line" aria-label="Code file">
          <TabsTrigger value="code">
            <CodeLanguageLabel language={language} filename={filename} />
          </TabsTrigger>
        </TabsList>
      )}
      <button
        type="button"
        aria-label="Copy code"
        title={copied ? "Copied!" : "Copy code"}
        onClick={onCopy}
        className="ml-auto inline-flex size-9 shrink-0 items-center justify-center hover:bg-muted focus-visible:outline-2 focus-visible:outline-ring"
      >
        <CopyFeedback copied={copied} />
      </button>
    </div>
  );
}

const CodeBlockRenderer = memo(function CodeBlockRenderer({
  code,
  language,
  filename,
  showLineNumbers,
  packageManager,
}: {
  code: string;
  language: string;
  filename: string;
  showLineNumbers: boolean;
  packageManager?: string;
}) {
  const languageId =
    (
      {
        js: "javascript",
        ts: "typescript",
        sh: "bash",
        shell: "bash",
        html: "markup",
        xml: "markup",
        py: "python",
      } as Record<string, string>
    )[language.toLowerCase()] ?? language.toLowerCase();
  return (
    <pre
      tabIndex={0}
      aria-label={
        filename
          ? `Code from ${filename}`
          : packageManager
            ? `${packageManager} installation command`
            : `${language || "Plain text"} code`
      }
      className="flex max-w-full gap-4 overflow-x-auto p-4 font-mono text-sm leading-6 focus-visible:outline-2 focus-visible:outline-ring"
    >
      <Highlight prism={Prism} code={code} language={languageId} theme={prismTheme}>
        {({ tokens, getLineProps, getTokenProps }) => (
          <code className="min-w-max font-mono">
            {tokens.map((line, index) => (
              <div key={index} {...getLineProps({ line })} className="flex min-w-full">
                {showLineNumbers && (
                  <span
                    aria-hidden="true"
                    className="mr-4 shrink-0 select-none text-right text-muted-foreground"
                  >
                    {index + 1}
                  </span>
                )}
                <span>
                  {line.map((token, key) => (
                    <span key={key} {...getTokenProps({ token })} />
                  ))}
                </span>
              </div>
            ))}
          </code>
        )}
      </Highlight>
    </pre>
  );
});

const PackageManagerTabs = memo(function PackageManagerTabs() {
  return (
    <TabsList variant="line" aria-label="Package manager">
      {(["bun", "npm", "pnpm", "yarn"] as const).map((option) => {
        const ManagerIcon = managerIcons[option];
        return (
          <TabsTrigger key={option} value={option}>
            <ManagerIcon
              width={16}
              height={16}
              aria-hidden="true"
              focusable="false"
              className="shrink-0"
            />
            {option}
          </TabsTrigger>
        );
      })}
    </TabsList>
  );
});

const CodeLanguageLabel = memo(function CodeLanguageLabel({
  language,
  filename,
}: {
  language: string;
  filename: string;
}) {
  const LanguageIcon = languageIcons[language.toLowerCase()] ?? FileCode;
  return (
    <span className="flex min-w-0 items-center gap-2 font-mono text-xs text-muted-foreground">
      <LanguageIcon
        width={16}
        height={16}
        aria-hidden="true"
        focusable="false"
        className="shrink-0"
      />
      <span className="truncate">{filename || language || "Code"}</span>
    </span>
  );
});

"use client";

import { memo } from "react";
import * as motion from "motion/react-client";
import { useReducedMotion } from "motion/react";

export const CopyFeedback = memo(function CopyFeedback({ copied = false }: { copied?: boolean }) {
  const reducedMotion = useReducedMotion();
  const transition = { duration: reducedMotion ? 0 : 0.22, ease: "easeInOut" as const };

  return (
    <motion.svg
      aria-hidden="true"
      focusable="false"
      width={16}
      height={16}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={2}
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      <motion.path
        d="M 15 9 L 15 4 L 4 4 L 4 15 L 9 15"
        initial={false}
        animate={{ opacity: copied ? 0 : 1 }}
        transition={transition}
      />
      <motion.path
        initial={false}
        animate={{
          d: copied
            ? "M 5 12 L 9 16 L 12.5 12.5 L 16 9 L 20 5"
            : "M 9 9 L 20 9 L 20 20 L 9 20 L 9 9",
        }}
        transition={transition}
      />
    </motion.svg>
  );
});

"use client";

import {
  createContext,
  useContext,
  useId,
  useState,
  useCallback,
  useMemo,
  type ComponentProps,
} from "react";
import { cn } from "cn";

interface TabsProps extends Omit<ComponentProps<"div">, "defaultValue" | "onChange"> {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  orientation?: "horizontal" | "vertical";
}

const TabsContext = createContext<{
  id: string;
  value?: string;
  orientation: "horizontal" | "vertical";
  variant: "default" | "line";
  select: (value: string) => void;
} | null>(null);

function useTabs() {
  const context = useContext(TabsContext);
  if (!context) throw new Error("Tabs components must be rendered inside Tabs.");
  return context;
}

export function Tabs({
  className,
  value,
  defaultValue,
  onValueChange,
  orientation = "horizontal",
  children,
  ...props
}: TabsProps) {
  const id = useId();
  const [selected, setSelected] = useState(defaultValue);
  const select = useCallback(
    (next: string) => {
      if (value === undefined) setSelected(next);
      onValueChange?.(next);
    },
    [value, onValueChange],
  );
  const context = useMemo(
    () => ({ id, value: value ?? selected, orientation, variant: "default" as const, select }),
    [id, value, selected, orientation, select],
  );
  return (
    <TabsContext.Provider value={context}>
      <div
        {...props}
        data-slot="tabs"
        data-orientation={orientation}
        className={cn(
          "group/tabs flex w-full gap-2 data-[orientation=horizontal]:flex-col",
          className,
        )}
      >
        {children}
      </div>
    </TabsContext.Provider>
  );
}

function tabsListVariants({ variant = "default" }: { variant?: "default" | "line" } = {}) {
  return cn(
    "group/tabs-list inline-flex w-fit items-center justify-center text-muted-foreground group-data-[orientation=vertical]/tabs:h-fit group-data-[orientation=vertical]/tabs:flex-col",
    variant === "line" ? "gap-1 bg-transparent" : "rounded-lg bg-muted dark:bg-[#131313] p-0.5",
  );
}

export function TabsList({
  className,
  variant = "default",
  onKeyDown,
  ...props
}: ComponentProps<"div"> & { variant?: "default" | "line" }) {
  const tabs = useTabs();
  const { orientation } = tabs;
  return (
    <TabsContext.Provider value={{ ...tabs, variant }}>
      <div
        {...props}
        role="tablist"
        aria-orientation={orientation}
        data-slot="tabs-list"
        data-variant={variant}
        className={cn(tabsListVariants({ variant }), className)}
        onKeyDown={(event) => {
          onKeyDown?.(event);
          if (event.defaultPrevented) return;
          const triggers = [
            ...event.currentTarget.querySelectorAll<HTMLButtonElement>(
              '[role="tab"]:not(:disabled)',
            ),
          ].filter((tab) => tab.closest('[role="tablist"]') === event.currentTarget);
          const index = triggers.indexOf(event.target as HTMLButtonElement);
          if (index < 0) return;
          const forward = orientation === "horizontal" ? "ArrowRight" : "ArrowDown";
          const backward = orientation === "horizontal" ? "ArrowLeft" : "ArrowUp";
          const next =
            event.key === "Home"
              ? triggers[0]
              : event.key === "End"
                ? triggers.at(-1)
                : event.key === forward
                  ? triggers[(index + 1) % triggers.length]
                  : event.key === backward
                    ? triggers[(index - 1 + triggers.length) % triggers.length]
                    : undefined;
          if (!next) return;
          event.preventDefault();
          next.focus();
          next.click();
        }}
      />
    </TabsContext.Provider>
  );
}

export function TabsTrigger({
  className,
  value,
  disabled,
  onClick,
  ...props
}: Omit<ComponentProps<"button">, "value"> & { value: string }) {
  const tabs = useTabs();
  const active = !disabled && tabs.value === value;
  const key = encodeURIComponent(value);
  return (
    <button
      {...props}
      type="button"
      role="tab"
      id={`${tabs.id}-tab-${key}`}
      aria-controls={`${tabs.id}-panel-${key}`}
      aria-selected={active}
      disabled={disabled}
      tabIndex={active || (tabs.value === undefined && !disabled) ? 0 : -1}
      data-slot="tabs-trigger"
      data-active={active ? "" : undefined}
      className={cn(
        "relative inline-flex min-h-8 flex-1 items-center justify-center gap-1.5 rounded-md border border-transparent px-3 py-1 text-sm font-medium whitespace-nowrap text-muted-foreground transition-colors hover:text-foreground focus-visible:outline-2 focus-visible:outline-ring disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0 group-data-[orientation=vertical]/tabs:w-full group-data-[orientation=vertical]/tabs:justify-start",
        tabs.variant === "line"
          ? "data-active:bg-transparent data-active:text-foreground after:absolute after:bg-foreground after:opacity-0 after:transition-opacity data-active:after:opacity-100 group-data-[orientation=horizontal]/tabs:after:inset-x-0 group-data-[orientation=horizontal]/tabs:after:-bottom-1 group-data-[orientation=horizontal]/tabs:after:h-0.5 group-data-[orientation=vertical]/tabs:after:inset-y-0 group-data-[orientation=vertical]/tabs:after:-right-1 group-data-[orientation=vertical]/tabs:after:w-0.5"
          : "data-active:bg-secondary/15 dark:data-active:bg-[#282727] data-active:text-foreground",
        className,
      )}
      onClick={(event) => {
        onClick?.(event);
        if (!event.defaultPrevented && !disabled) tabs.select(value);
      }}
    />
  );
}

export function TabsContent({
  className,
  value,
  ...props
}: ComponentProps<"div"> & { value: string }) {
  const tabs = useTabs();
  const key = encodeURIComponent(value);
  return (
    <div
      {...props}
      role="tabpanel"
      id={`${tabs.id}-panel-${key}`}
      aria-labelledby={`${tabs.id}-tab-${key}`}
      hidden={tabs.value !== value}
      tabIndex={0}
      data-slot="tabs-content"
      className={cn(
        "min-w-0 flex-1 rounded-lg focus-visible:outline-2 focus-visible:outline-ring",
        "typography-body",
        className,
      )}
    />
  );
}

"use client";

import type { ReactNode } from "react";

export type ToastVariant = "neutral" | "info" | "success" | "warning" | "error";

export interface ToastOptions {
  description?: string;
  variant?: ToastVariant;
  duration?: number;
  action?: ReactNode;
}

interface Notification extends ToastOptions {
  id: number;
  message: string;
}

const empty: readonly Notification[] = [];
let notifications = empty;
let nextId = 0;
const listeners = new Set<() => void>();

function publish(next: readonly Notification[]) {
  notifications = next;
  listeners.forEach((listener) => listener());
}

function show(message: string, options: ToastOptions = {}) {
  const id = ++nextId;
  publish([{ ...options, id, message }, ...notifications].slice(0, 3));
  return id;
}

export const toast = Object.assign(show, {
  neutral: (message: string, options?: ToastOptions) =>
    show(message, { ...options, variant: "neutral" }),
  info: (message: string, options?: ToastOptions) => show(message, { ...options, variant: "info" }),
  success: (message: string, options?: ToastOptions) =>
    show(message, { ...options, variant: "success" }),
  warning: (message: string, options?: ToastOptions) =>
    show(message, { ...options, variant: "warning" }),
  error: (message: string, options?: ToastOptions) =>
    show(message, { ...options, variant: "error" }),
  dismiss: (id?: number) =>
    publish(id === undefined ? empty : notifications.filter((item) => item.id !== id)),
});

export const toastStore = {
  subscribe(listener: () => void) {
    listeners.add(listener);
    return () => {
      listeners.delete(listener);
    };
  },
  getSnapshot: () => notifications,
  getServerSnapshot: () => empty,
};
